import{_ as t,o,c as a,a3 as d}from"./chunks/framework.I6s8z2kk.js";const h=JSON.parse('{"title":"Settlements and payouts","description":"","frontmatter":{},"headers":[],"relativePath":"dev/domain/settlements.md","filePath":"dev/domain/settlements.md"}'),n={name:"dev/domain/settlements.md"};function c(r,e,i,s,l,p){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="settlements-and-payouts" tabindex="-1">Settlements and payouts <a class="header-anchor" href="#settlements-and-payouts" aria-label="Permalink to &quot;Settlements and payouts&quot;">​</a></h1><p>The <strong>Settlements</strong> module tracks what the platform owes each center and pays it out.</p><h2 id="the-center-ledger" tabindex="-1">The center ledger <a class="header-anchor" href="#the-center-ledger" aria-label="Permalink to &quot;The center ledger&quot;">​</a></h2><p><code>CenterLedgerEntry</code> rows are <strong>appended</strong>, never edited. Types:</p><table tabindex="0"><thead><tr><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>payment</code></td><td>An online payment credited to the center</td></tr><tr><td><code>refund</code></td><td>A refund debited on an online payment</td></tr><tr><td><code>platform_fee</code></td><td>The platform fee debited</td></tr><tr><td><code>fee_reversal</code></td><td>The fee taken back (cancel or full refund)</td></tr><tr><td><code>platform_subsidy</code></td><td>A platform-funded discount credited to the center</td></tr><tr><td><code>subsidy_reversal</code></td><td>The subsidy taken back</td></tr><tr><td><code>baseline_adjustment</code></td><td>A correction to the balance finance confirmed for a migrated center; <code>purchase_id</code> is null</td></tr></tbody></table><p><code>SyncPurchaseLedger</code> brings a center purchase&#39;s entries in line with its current state <strong>by appending the difference</strong>. Running it again, or for events handled out of order, changes nothing.</p><ul><li>Online payments are credited and become <strong>available after a hold period</strong>. Refunds on them are debited.</li><li><strong>Cash and manual payments stay with the center</strong>; they never enter the ledger as credits.</li><li>While the purchase is <code>confirmed</code> or <code>completed</code> and its fee is not reversed, the platform fee is debited and the platform-funded discount is credited. Otherwise both are taken back.</li></ul><h2 id="financial-baselines" tabindex="-1">Financial baselines <a class="header-anchor" href="#financial-baselines" aria-label="Permalink to &quot;Financial baselines&quot;">​</a></h2><p>The legacy system&#39;s payouts are not migrated, so a migrated center&#39;s ledger says it is owed its whole history. <code>CenterFinancialBaseline</code> (one row per center) holds the figures finance confirms as of <code>cutoff_at</code>.</p><ul><li><code>migrator:purchases</code> creates a <strong>pending</strong> row (<code>confirmed_at</code> null) for every center that received a purchase; an existing row is left alone. Centers created in the new system have no row.</li><li><code>SetCenterFinancialBaseline</code> is the only way a baseline changes. The first confirmation fixes <code>cutoff_at</code>, freezes the snapshot from <code>CenterBaselineSnapshot</code> (<code>migrated_*</code>) and appends one <code>baseline_adjustment</code> entry of <code>target_balance - migrated_balance</code>, available at once. Later calls replace the targets and append only <code>new target_balance - previous target_balance</code>, so refunds and fees that land afterwards on old purchases are not cancelled out. A zero difference appends nothing.</li><li>The snapshot covers the center&#39;s purchases created up to the cutoff: <code>migrated_balance</code> is the net of their ledger entries not in a payout, <code>migrated_platform_fees</code> fees net of reversals, <code>migrated_refunds</code> refund entries, and <code>migrated_gross_sales</code> the totals of confirmed and completed purchases.</li><li>Only the balance becomes a ledger entry. <code>target_paid_out</code> is added to <code>paid_out</code> in <code>CenterBalance</code>; the fee, sales and refund targets correct <a href="./analytics">analytics</a> on the cutoff day. All targets except the balance are optional; null means no correction.</li><li><code>CenterBalance</code> returns <code>baseline_pending</code>, true while the row is unconfirmed.</li><li><code>CenterFinancialBaselineConfirmed</code> fires after commit.</li></ul><p><code>GET</code> / <code>PUT admin/centers/{center}/financial-baseline</code> need <code>payouts.baseline</code> (<code>CenterPayoutPolicy::manageBaseline</code>), which <code>payouts.manage</code> does not include. <code>PUT</code> takes <code>cutoff_at</code> (required the first time, not in the future, 422 if changed later), <code>target_balance</code> (signed), the optional <code>target_platform_fees</code>, <code>target_paid_out</code>, <code>target_gross_sales</code>, <code>target_refunds</code> (≥ 0) and a <code>note</code>. Before confirmation <code>GET</code> shows the snapshot as of now.</p><h2 id="payouts" tabindex="-1">Payouts <a class="header-anchor" href="#payouts" aria-label="Permalink to &quot;Payouts&quot;">​</a></h2><p><code>CenterPayout</code> status: <code>pending</code>, <code>paid</code>, <code>cancelled</code>.</p><p><code>purchase:generate-payouts</code> runs <strong>weekly on Sunday at 00:00</strong> (or manually with <code>--cutoff=</code>). <code>GenerateCenterPayouts</code> creates <strong>one pending payout per center</strong> for its unpaid ledger entries that are available at the cutoff:</p><ul><li>Debits net against credits.</li><li>A center whose net is zero or negative keeps its entries for the next run.</li><li>The bank account is <strong>optional</strong>: a center without <code>payout_iban</code> still gets its payout, and the payout&#39;s <code>iban</code>, <code>account_name</code> and <code>bank_name</code> are null (copied as they were at creation). Finance must obtain the account before transferring.</li><li>A center already paid out for the same cutoff is skipped.</li><li>A center whose financial baseline is <strong>pending</strong> is skipped until it is confirmed.</li></ul><p>A system user with <code>payouts.manage</code> marks a payout paid or cancels it. <code>CenterPayoutPaid</code> fires an event that notifies the center.</p><h2 id="payout-invoices" tabindex="-1">Payout invoices <a class="header-anchor" href="#payout-invoices" aria-label="Permalink to &quot;Payout invoices&quot;">​</a></h2><p><code>GET admin/payouts/{payout}/invoice?locale=ar|en</code> (default <code>ar</code>) streams a PDF that <code>PayoutInvoiceRenderer</code> builds from the Blade view <code>settlements::invoices.payout</code> with <strong>mPDF</strong>. mPDF handles Arabic shaping and right-to-left layout, and a new instance is created for each render (Octane). The invoice number is <code>PO-</code> plus the zero-padded payout id. Money is formatted from halalas without floats, and dates are in UTC. A cancelled payout gets a watermark. Labels come from <code>lang/{en,ar}/invoice.php</code>.</p><p>The layout is the singleton <code>PayoutInvoiceTemplate</code> (one row created by its migration; read it with <code>current()</code>):</p><ul><li>en/ar translatable company name, address, <code>header_note</code> and <code>footer_note</code>.</li><li>Tax and CR numbers, email, phone and <code>accent_color</code> (<code>#RRGGBB</code>).</li><li>Four <code>show_*</code> section flags.</li><li>A <code>logo</code> media collection (single JPEG/PNG file).</li></ul><p>Notes are cleaned with <code>LegalHtmlSanitizer</code>. Saving goes through <code>PayoutInvoiceTemplateService</code>, and <code>applyAttributes()</code> replaces each translatable field&#39;s locales so a cleared locale is removed. The logo is a temporary upload promoted with <code>TemporaryMediaService</code>; <code>null</code> removes it. <code>POST admin/payout-invoice-template/preview</code> renders the unsaved body (plus <code>locale</code> and an optional <code>payout_id</code>, otherwise in-memory sample data) and saves nothing. The template endpoints authorize <code>CenterPayoutPolicy::manageInvoiceTemplate</code> (<code>payouts.manage</code>).</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Endpoints</th></tr></thead><tbody><tr><td>Center</td><td><code>centers/{center}/balance</code>, <code>payout-account</code> (set by the primary user), <code>payouts</code>, <code>payouts/{payout}</code>, ledger-related exports</td></tr><tr><td>Admin</td><td><code>admin/payouts</code>, <code>admin/payouts/{payout}</code>, <code>payouts/{payout}/mark-paid</code>, <code>payouts/{payout}/cancel</code>, <code>payouts/{payout}/invoice</code>, <code>admin/payout-invoice-template</code> (show, update, <code>preview</code>), <code>admin/centers/{center}/ledger</code>, <code>ledger/export</code>, <code>admin/centers/{center}/financial-baseline</code> (show, update)</td></tr></tbody></table><p>Admin lists take <code>sort</code>, <code>-</code> for descending, newest first without it (<a href="./../conventions/coding#list-sorting">List sorting</a>): <code>admin/payouts</code> accepts <code>CenterPayoutController::SORTS</code> (<code>created_at</code>, <code>amount</code>, <code>period_end</code>, <code>entries_count</code>); the ledger and its export accept <code>CenterLedgerQuery::SORTS</code> (<code>created_at</code>, <code>amount</code>, <code>available_at</code>).</p>',24)])])}const m=t(n,[["render",c]]);export{h as __pageData,m as default};
